<?php
// Included by the real WordPress suite before its process-wide autosave transition.
register_post_type('alify_deep', array('public' => true, 'show_ui' => true));
$deep_toggle = test_field('toggle', 'true_false'); $deep_detail = test_field('detail', 'text', true); $deep_detail['condition'] = array('field' => $deep_toggle['key'], 'operator' => 'equals', 'value' => '1');
$deep_card = test_field('card', 'group'); $deep_card['sub_fields'] = array($deep_toggle, $deep_detail);
$deep_flex = test_field('flex', 'flexible'); $deep_flex['layouts'] = array(array('name' => 'hero', 'key' => 'layout_deep_hero', 'label' => 'Hero', 'sub_fields' => array($deep_card)));
$deep_rows = test_field('rows', 'repeater'); $deep_rows['sub_fields'] = array($deep_flex);
$deep_root = test_field('deep_root', 'group'); $deep_root['sub_fields'] = array($deep_rows);
expect_same(true, alify_register_field_group(array('key' => 'deep_suite', 'title' => 'Deep suite', 'location' => 'alify_deep', 'fields' => array($deep_root))), 'Four bounded mixed container levels register');
$deep_post = fixture_post('alify_deep'); $deep_value = array('rows' => array(array('flex' => array(array('layout' => 'hero', 'fields' => array('card' => array('toggle' => '1', 'detail' => 'Deep kept')))))));
$deep_payload = Alify_CF_Publication::stored_payload($deep_root, $deep_value);
expect_same(true, alify_update_field('deep_root', $deep_payload, $deep_post), 'Nested Group / Repeater / Flexible / Group persists canonical value'); expect_same($deep_value, alify_get_field('deep_root', $deep_post), 'Nested getters never add transport markers');
$deep_edited = $deep_payload; $deep_edited['fields']['rows']['rows'][0]['flex']['rows'][0]['fields']['card']['fields']['detail'] = 'Edited deep';
expect_same(true, is_wp_error(alify_update_field('deep_root', $deep_edited, $deep_post)), 'Edited nested existing rows never guess old parents by ordinal');
$deep_edited['fields']['rows']['rows'][0]['__row_origin'] = Alify_CF_Scoped_Conditions::origin($deep_value['rows'][0]); $deep_edited['fields']['rows']['rows'][0]['flex']['rows'][0]['fields']['__row_origin'] = Alify_CF_Scoped_Conditions::origin($deep_value['rows'][0]['flex'][0]['fields']);
expect_same(true, alify_update_field('deep_root', $deep_edited, $deep_post), 'Nested edits use each containing row original identity');
$deep_before = alify_get_field('deep_root', $deep_post); $deep_bad = $deep_edited; $deep_bad['fields']['rows']['rows'][0]['__row_origin'] = Alify_CF_Scoped_Conditions::origin($deep_before['rows'][0]); $deep_bad['fields']['rows']['rows'][0]['flex']['rows'][0]['fields']['__row_origin'] = Alify_CF_Scoped_Conditions::origin($deep_before['rows'][0]['flex'][0]['fields']); $deep_bad['fields']['rows']['rows'][0]['flex']['rows'][0]['fields']['card']['fields']['toggle'] = '0'; $deep_bad['fields']['rows']['rows'][0]['flex']['rows'][0]['fields']['card']['fields']['detail'] = 'Forged hidden';
expect_same(true, is_wp_error(alify_update_field('deep_root', $deep_bad, $deep_post)), 'Explicit hidden-child audit recurses through unconditioned parent containers'); expect_same($deep_before, alify_get_field('deep_root', $deep_post), 'Nested audit rejects atomically');
$too_deep = $deep_root; $too_deep['sub_fields'][0]['sub_fields'][0]['layouts'][0]['sub_fields'][0]['sub_fields'] = array($deep_card); $deep_errors = array(); Alify_CF::validate_schema(array($too_deep), 'alify_deep', Alify_CF_API::groups('alify_deep')[0]['id'], $deep_errors); expect_same(true, (bool) $deep_errors, 'Fifth container level rejects before recursion');
expect_same(false, Alify_CF_Composition::budget(array('value' => str_repeat('x', 1048577))), 'Global value byte budget rejects oversized strings'); expect_same(false, Alify_CF_Composition::budget(array_fill(0, 20001, 'x')), 'Global structural node budget bounds breadth'); expect_same(12, Alify_CF_Transfer::minimum_version(array($deep_root), 'alify_deep'), 'Nested composition declares schema v12');
$deep_doc = array('format' => 'alify-custom-field', 'version' => 11, 'group' => array('title' => 'Nested export', 'location' => 'alify_deep', 'fields' => array($deep_root))); Alify_CF_API::unregister_group('deep_suite'); expect_same(true, is_wp_error(Alify_CF_Transfer::import_json(wp_json_encode($deep_doc), wp_create_nonce('alify_cf_import'))), 'Old schema envelopes cannot accept nested features'); $deep_doc['version'] = 12; $deep_import = Alify_CF_Transfer::import_json(wp_json_encode($deep_doc), wp_create_nonce('alify_cf_import')); expect_same(true, is_int($deep_import), 'Portable schema v12 imports bounded composition'); $fixtures[] = $deep_import;

register_post_type('alify_pairs', array('public' => true, 'show_ui' => true));
$pair_from = test_field('pair_from', 'relationship'); $pair_from['post_types'] = array('alify_pairs'); $pair_from['post_statuses'] = array('draft', 'publish'); $pair_from['api_read'] = true; $pair_from['api_write'] = true; $pair_to = $pair_from; $pair_to['name'] = 'pair_to'; $pair_to['key'] = 'field_pair_to';
$pair_text = test_field('pair_text'); $pair_text['api_read'] = true; $pair_text['api_write'] = true; $pair_text['public_output'] = true;
expect_same(true, alify_register_field_group(array('key' => 'pairs_suite', 'title' => 'Pairs', 'location' => 'alify_pairs', 'fields' => array($pair_from, $pair_to, $pair_text, test_field('pair_secret', 'password')))), 'Paired post fields register normally');
expect_same(true, alify_register_bidirectional_pair('suite_pair', array('type' => 'alify_pairs', 'field' => 'pair_from'), array('type' => 'alify_pairs', 'field' => 'pair_to')), 'Explicit post-reference pair registers');
expect_same(true, is_wp_error(alify_register_bidirectional_pair('suite_collision', array('type' => 'alify_pairs', 'field' => 'pair_from'), array('type' => 'alify_pairs', 'field' => 'other'))), 'An endpoint cannot silently participate in multiple pairs');
$pair_a = fixture_post('alify_pairs'); $pair_b = fixture_post('alify_pairs'); $pair_c = fixture_post('alify_pairs'); $pair_payload = function($ids) { return array('__complete' => '1', 'ids' => array_map('strval', $ids)); };
expect_same(true, alify_update_field('pair_from', $pair_payload(array($pair_b, $pair_c)), $pair_a), 'Paired API updates forward and reverse lists'); expect_same(array($pair_a), alify_get_field('pair_to', $pair_b), 'First reverse membership added'); expect_same(array($pair_a), alify_get_field('pair_to', $pair_c), 'Second reverse membership added');
expect_same(true, alify_update_field('pair_to', $pair_payload(array()), $pair_b), 'Reverse-side edit removes matching forward membership'); expect_same(array($pair_c), alify_get_field('pair_from', $pair_a), 'Unrelated forward order/membership retained');
expect_same(true, is_wp_error(alify_update_field('pair_from', $pair_payload(array($pair_a)), $pair_a)), 'Self links reject without mutation');
$pair_throw = function($updates, $id) use ($pair_b) { if ((int) $id === $pair_b) { throw new RuntimeException('Injected paired write failure'); } }; add_action('alify_cf/before_api_write', $pair_throw, 10, 2); $pair_failed = alify_update_field('pair_from', $pair_payload(array($pair_b)), $pair_a); remove_action('alify_cf/before_api_write', $pair_throw, 10);
expect_same('alify_pair_failed', $pair_failed->get_error_code(), 'Failure after earlier object writes triggers coordinated rollback'); expect_same(array($pair_c), alify_get_field('pair_from', $pair_a), 'Forward snapshot restored'); expect_same(array($pair_a), alify_get_field('pair_to', $pair_c), 'Already changed reverse snapshot restored');
$pair_race = function($updates, $id) use ($pair_a, $pair_b, $pair_c) { if ((int) $id === $pair_b) { update_post_meta($pair_a, '_alify_cf_pair_from', array($pair_c, $pair_b)); throw new RuntimeException('Injected concurrent edit'); } }; add_action('alify_cf/before_api_write', $pair_race, 10, 2); $pair_failed = alify_update_field('pair_from', $pair_payload(array($pair_b)), $pair_a); remove_action('alify_cf/before_api_write', $pair_race, 10);
expect_same('alify_rollback_failed', $pair_failed->get_error_code(), 'Unknown editorial changes fail closed rather than being overwritten'); expect_same(array($pair_c, $pair_b), alify_get_field('pair_from', $pair_a), 'Optimistic rollback preserves unknown changes'); $pair_backup = $pair_failed->get_error_data()['backup']; expect_same(true, is_array(Alify_CF_Bidirectional::backup($pair_backup)), 'Creator with all object permissions can inspect retained recovery backup'); delete_transient($pair_backup); update_post_meta($pair_a, '_alify_cf_pair_from', array($pair_c));
wp_set_current_user(0); expect_same(true, is_wp_error(alify_update_field('pair_from', $pair_payload(array()), $pair_a)), 'Unauthenticated paired writes reject'); expect_same(true, is_wp_error(Alify_CF_Bidirectional::backup($pair_backup)), 'Recovery snapshots never become public'); wp_set_current_user($admin->ID);
expect_same(false, get_option('alify_cf_pair_lock', false), 'Pair coordinator releases its ownership lock after success/failure');

if (!defined('ALIFY_CF_ABILITIES')) { define('ALIFY_CF_ABILITIES', true); }
expect_same(true, Alify_CF_Integrations::ability_allowed(array('post_id' => $pair_a)), 'Ability permission checks concrete editable post'); expect_same(false, Alify_CF_Integrations::ability_allowed(array('post_id' => (string) $pair_a)), 'Ability ID shape stays strict');
expect_same(array('saved' => true), Alify_CF_Integrations::ability(array('post_id' => $pair_a, 'values' => array('pair_text' => 'Ability value')), true), 'Ability writes only explicitly API-exposed fields');
$ability_read = Alify_CF_Integrations::ability(array('post_id' => $pair_a)); expect_same('Ability value', $ability_read['values']['pair_text'], 'Ability read reuses protected field exposure contract'); expect_same(false, array_key_exists('pair_secret', $ability_read['values']), 'Ability never reads unexposed secrets'); expect_same(true, is_wp_error(Alify_CF_Integrations::ability(array('post_id' => $pair_a, 'values' => array('pair_secret' => 'forged')), true)), 'Ability cannot bypass write exposure'); wp_set_current_user(0); expect_same(true, is_wp_error(Alify_CF_Integrations::ability(array('post_id' => $pair_a))), 'Anonymous ability access rejects'); wp_set_current_user($admin->ID);
if (function_exists('wp_get_ability')) { $ability = wp_get_ability('alify/read-fields'); expect_same(true, is_object($ability), 'Native WordPress Abilities registry accepts the opt-in definition'); expect_same('Ability value', $ability->execute(array('post_id' => $pair_a))['values']['pair_text'], 'Native registered ability executes protected reader'); }
$release_prefix = 'https://github.com/alifywork/fieldsPlugin/releases/download/v0.99.0/'; $release_case = array('tag_name' => 'v0.99.0', 'draft' => false, 'prerelease' => false, 'assets' => array(array('name' => 'alify-custom-field.zip', 'browser_download_url' => $release_prefix . 'alify-custom-field.zip'), array('name' => 'alify-custom-field.zip.sha256', 'browser_download_url' => $release_prefix . 'alify-custom-field.zip.sha256')));
expect_same('0.99.0', Alify_CF_Updates::parse($release_case)['version'], 'Managed updater accepts stable explicitly packaged release'); $release_bad = $release_case; $release_bad['assets'][0]['browser_download_url'] = 'https://attacker.invalid/package.zip'; expect_same(null, Alify_CF_Updates::parse($release_bad), 'Managed updater rejects untrusted package hosts/paths'); $release_bad = $release_case; $release_bad['prerelease'] = true; expect_same(null, Alify_CF_Updates::parse($release_bad), 'Managed updater never silently opts into prereleases'); $release_bad = $release_case; array_pop($release_bad['assets']); expect_same(null, Alify_CF_Updates::parse($release_bad), 'Managed updater requires checksum asset before offering a version'); expect_same(null, Alify_CF_Updates::release(), 'Managed update checks are dormant without explicit opt-in');
expect_same(true, is_wp_error(Alify_CF_Updates::download(false, $release_prefix . 'alify-custom-field.zip')), 'A stale managed package cannot bypass the disabled checksum downloader'); expect_same(false, Alify_CF_Updates::download(false, 'https://example.invalid/other.zip'), 'Updater leaves unrelated plugin packages alone');
expect_same(true, is_array(alify_support_snapshot()), 'Administrator can obtain explicit local support diagnostics'); wp_set_current_user(0); expect_same(true, is_wp_error(alify_support_snapshot()), 'Support diagnostics require admin permission'); wp_set_current_user($admin->ID);
expect_same(null, alify_get_order_field('anything', 1), 'WooCommerce adapter is dormant without provider/opt-in'); expect_same(true, is_wp_error(alify_update_order_fields(array('anything' => 'x'), 1)), 'Missing provider never falls back to postmeta order writes');
expect_same(null, alify_get_translated_field('pair_text', $pair_a, 'fr'), 'Translation adapter is dormant without provider/opt-in'); expect_same(true, is_wp_error(alify_register_translation_policy('bad-name', 'copy')), 'Translation policies validate canonical field names'); expect_same(true, is_wp_error(alify_register_translation_policy('pair_text', 'arbitrary')), 'Translation policies reject undefined copy modes');
Alify_CF_API::unregister_group('pairs_suite');
